// src/App.js
import React, { useState, useEffect } from "react";
import { Card, CardContent } from "@/components/ui/card";
import { Button } from "@/components/ui/button";

const App = () => {
  const [timeLeft, setTimeLeft] = useState(84 * 60 * 60); // 84 hours in seconds
  const [surveyVisible, setSurveyVisible] = useState(false);
  const [formData, setFormData] = useState({
    q1: "",
    q2: "",
    q3: "",
    q4: "",
    q5: "",
    email: "",
  });

  useEffect(() => {
    if (timeLeft <= 0) return;
    const interval = setInterval(() => {
      setTimeLeft((prevTime) => prevTime - 1);
    }, 1000);

    return () => clearInterval(interval);
  }, [timeLeft]);

  const formatTime = (seconds) => {
    const hours = Math.floor(seconds / 3600);
    const minutes = Math.floor((seconds % 3600) / 60);
    const secs = seconds % 60;
    return `${hours.toString().padStart(2, "0")}:${minutes
      .toString()
      .padStart(2, "0")}:${secs.toString().padStart(2, "0")}`;
  };

  const handleInputChange = (e) => {
    const { name, value } = e.target;
    setFormData((prevData) => ({ ...prevData, [name]: value }));
  };

  const handleSubmit = (e) => {
    e.preventDefault();
    console.log("Survey Submitted:", formData);
    alert("Thank you for your feedback!");
    setFormData({
      q1: "",
      q2: "",
      q3: "",
      q4: "",
      q5: "",
      email: "",
    });
  };

  return (
    <div className="flex flex-col items-center p-10 bg-gray-100 min-h-screen">
      <h1 className="text-4xl font-bold mb-4 text-purple-700">PlasmaPals</h1>
      <Card className="w-full max-w-xl p-6 bg-white rounded-lg shadow-md">
        <CardContent>
          <p className="text-lg mb-4">
            PlasmaPals is dedicated to educating people about the importance of
            plasma donation, its safety, and how you can make a difference.
          </p>
          <p className="text-2xl mb-4">Time until next survey: {formatTime(timeLeft)}</p>
          {timeLeft <= 0 && !surveyVisible && (
            <Button
              onClick={() => setSurveyVisible(true)}
              className="bg-purple-500 text-white px-4 py-2 rounded-md"
            >
              Take the Survey
            </Button>
          )}
        </CardContent>
      </Card>

      {surveyVisible && (
        <Card className="w-full max-w-xl p-6 bg-white rounded-lg shadow-md mt-6">
          <CardContent>
            <h2 className="text-2xl mb-4">Weekly Update Survey</h2>
            <form onSubmit={handleSubmit}>
              {[
                "Was the time it took reasonable?",
                "Did you feel comfortable with the process?",
                "Did you feel that the staff was friendly and professional?",
                "Did you feel that you were properly compensated for your time?",
                "Were you satisfied with the overall experience?",
              ].map((question, index) => (
                <div key={index} className="mb-4">
                  <p>{question}</p>
                  <label>
                    <input
                      type="radio"
                      name={`q${index + 1}`}
                      value="true"
                      onChange={handleInputChange}
                      checked={formData[`q${index + 1}`] === "true"}
                      required
                    />
                    True
                  </label>
                  <label className="ml-4">
                    <input
                      type="radio"
                      name={`q${index + 1}`}
                      value="false"
                      onChange={handleInputChange}
                      checked={formData[`q${index + 1}`] === "false"}
                      required
                    />
                    False
                  </label>
                </div>
              ))}

              <div className="mb-4">
                <label className="block mb-2">
                  Your Email:
                  <input
                    type="email"
                    name="email"
                    value={formData.email}
                    onChange={handleInputChange}
                    className="w-full p-2 border rounded-md"
                    required
                  />
                </label>
              </div>

              <Button
                type="submit"
                className="bg-green-500 text-white px-4 py-2 rounded-md"
              >
                Submit Survey
              </Button>
            </form>
          </CardContent>
        </Card>
      )}
    </div>
  );
};

export default App;
